package com.tarapickle.identity.infrastructure.email; import com.tarapickle.identity.application.*; import com.tarapickle.identity.application.port.EmailPort; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Component; import org.springframework.transaction.event.*;
@Component @RequiredArgsConstructor public class EmailEventListener {private final EmailPort email; @TransactionalEventListener(phase=TransactionPhase.AFTER_COMMIT) public void send(EmailRequested e){if(e.kind()==EmailRequested.Kind.VERIFICATION)email.sendVerification(e.email(),e.token());else email.sendPasswordReset(e.email(),e.token());}}
